#include <string>

std::string convertToHtml(const std::string& text_in_quotes) {
    std::string html_text;
    html_text.reserve(text_in_quotes.size()); // optimize memory allocation

    // Add opening tag for HTML code
    html_text += "<code>";

    // Replace single quotes with HTML entities
    size_t pos = 0;
    while ((pos = text_in_quotes.find("'", pos)) != std::string::npos) {
